PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_331_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_331_guard;
INSERT INTO _migration_331_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_textiles_b005_031' AND NOT (q.topic_id IS 'topic_was_textiles_b005_7' AND q.subject_id IS 'subj_wassce_textiles' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why are fabric shears reserved for fabric?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Stop it and isolate power where applicable","B. The stitch-length regulator","C. Paper and hard materials dull their cutting edges","D. To check tension, stitch length, needle and thread"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The stated answer applies the governing subject principle directly and distinguishes it from the other same-topic alternatives. Therefore the correct answer is C: Paper and hard materials dull their cutting edges.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_textiles_b005_7' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_textiles_b005_031' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Clothing and Textiles practice aligned to official Ghana curriculum and WAEC subject evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
